52	/**
53	 * Builds .agent.md content from a configuration object using string formatting.
54	 * No YAML library required — generates valid YAML frontmatter via string templates.
55	 */
56	export function buildAgentMarkdown(config: AgentConfig): string {
57		const lines: string[] = ['---'];
58	
59		// Simple scalar fields
60		lines.push(`name: ${config.name}`);
61		lines.push(`description: ${config.description}`);
62		lines.push(`argument-hint: ${config.argumentHint}`);
63	
64		// Model (optional) — supports a single string or a priority list of models
65		if (config.model) {
66			if (Array.isArray(config.model)) {
67				const quoted = config.model.map(m => `'${m.replace(/'/g, '\'\'')}'`).join(', ');
68				lines.push(`model: [${quoted}]`);
69			} else {
70				lines.push(`model: ${config.model}`);
71			}
72		}
73		if (config.target) {
74			lines.push(`target: ${config.target}`);
75		}
76		if (config.disableModelInvocation) {
77			lines.push(`disable-model-invocation: true`);
78		}
79		if (config.userInvocable === false) {
80			lines.push(`user-invocable: false`);
81		}
82	
83		// Tools array - flow style for readability
84		// Escape single quotes by doubling them (YAML spec)
85		if (config.tools.length > 0) {
86			const quotedTools = config.tools.map(t => `'${t.replace(/'/g, '\'\'')}'`).join(', ');
87			lines.push(`tools: [${quotedTools}]`);
88		}
89	
90		// Agents array - same format as tools (empty array = no subagents allowed)
91		if (config.agents) {
92			const quotedAgents = config.agents.map(a => `'${a.replace(/'/g, '\'\'')}'`).join(', ');
93			lines.push(`agents: [${quotedAgents}]`);
94		}
95	
96		// Handoffs - block style for complex nested objects
97		// Escape prompts using single quotes (with doubled single quotes for internal quotes)
98		if (config.handoffs && config.handoffs.length > 0) {
99			lines.push('handoffs:');
100			for (const handoff of config.handoffs) {
101				lines.push(`  - label: ${handoff.label}`);
102				lines.push(`    agent: ${handoff.agent}`);
103				lines.push(`    prompt: '${handoff.prompt.replace(/'/g, '\'\'')}'`);
104				if (handoff.send !== undefined) {
105					lines.push(`    send: ${handoff.send}`);
106				}
107				if (handoff.showContinueOn !== undefined) {
108					lines.push(`    showContinueOn: ${handoff.showContinueOn}`);
109				}
110				if (handoff.model !== undefined) {
111					lines.push(`    model: ${handoff.model}`);
112				}
113			}
114		}
115	
116		lines.push('---');
117		lines.push(config.body);
118	
119		return lines.join('\n');
120	}
