60	/** Gets stateful markers from the messages, from the most to least recent */
61	export function* getAllStatefulMarkersAndIndicies(messages: readonly Raw.ChatMessage[]) {
62		for (let idx = messages.length - 1; idx >= 0; idx--) {
63			const message = messages[idx];
64			if (message.role === Raw.ChatRole.Assistant) {
65				for (const part of message.content) {
66					if (part.type === Raw.ChatCompletionContentPartKind.Opaque) {
67						const statefulMarker = rawPartAsStatefulMarker(part);
68						if (statefulMarker) {
69							yield { statefulMarker: statefulMarker, index: idx };
70						}
71					}
72				}
73			}
74		}
75		return undefined;
76	}
