79		for (const marker of getAllStatefulMarkersAndIndicies(messages)) {
80			if (marker.statefulMarker.modelId === modelId) {
81				return { statefulMarker: marker.statefulMarker.marker, index: marker.index };
82			}
83		}
84		return undefined;
85	}
